b='''// Transpose 4x4 byte groups with vector loads and register byte permutations.
// Read the full tile before overwriting it; only the math warps participate.
template <unsigned N>
__device__ __forceinline__ void transpose_weight_tile(std::uint8_t *data) {
  uint4 values[N / 32U];
#pragma unroll
  for (unsigned i = 0; i < N / 32U; ++i) {
    const auto index = threadIdx.x + i * 256U;
    const auto block = index / 1024U, row = index % 1024U / 32U * 4U, col = index % 32U * 4U;
    const auto *base = data + block * 16384U;
    const auto a = *reinterpret_cast<const unsigned *>(base + fp8::tile_offset(row, col));
    const auto b = *reinterpret_cast<const unsigned *>(base + fp8::tile_offset(row + 1U, col));
    const auto c = *reinterpret_cast<const unsigned *>(base + fp8::tile_offset(row + 2U, col));
    const auto d = *reinterpret_cast<const unsigned *>(base + fp8::tile_offset(row + 3U, col));
    const auto lo0 = __byte_perm(a,b,0x5140), lo1 = __byte_perm(c,d,0x5140);
    const auto hi0 = __byte_perm(a,b,0x7362), hi1 = __byte_perm(c,d,0x7362);
    values[i] = make_uint4(__byte_perm(lo0,lo1,0x5410), __byte_perm(lo0,lo1,0x7632),
                          __byte_perm(hi0,hi1,0x5410), __byte_perm(hi0,hi1,0x7632));
  }
  fp8::MathSync::sync();
#pragma unroll
  for (unsigned i = 0; i < N / 32U; ++i) {
    const auto index = threadIdx.x + i * 256U;
    const auto block = index / 1024U, row = index % 1024U / 32U * 4U, col = index % 32U * 4U;
    auto *base = data + block * 16384U;
    *reinterpret_cast<unsigned *>(base + fp8::tile_offset(col, row)) = values[i].x;
    *reinterpret_cast<unsigned *>(base + fp8::tile_offset(col + 1U, row)) = values[i].y;
    *reinterpret_cast<unsigned *>(base + fp8::tile_offset(col + 2U, row)) = values[i].z;
    *reinterpret_cast<unsigned *>(base + fp8::tile_offset(col + 3U, row)) = values[i].w;
  }
  asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
  fp8::MathSync::sync();
}

